            hidden.push(i);
    }
    const defsOf = hidden.map((i) => t.cards[i].d);
    for (let i = defsOf.length - 1; i > 0; i -= 1) {
        const j = Math.floor(Math.random() * (i + 1));
        const x = defsOf[i];
        defsOf[i] = defsOf[j];
        defsOf[j] = x;
    }
    hidden.forEach((i, k) => {
        t.cards[i].d = defsOf[k];
