//   - free play (build / POP / retreat / setup): every card the seat can act on outlined
//     (`playable`, private to that seat), a click on a card opening that card's options
//     (`movesFor`), right-click menus as before, and the seat's no-card moves (Pass, End step...)
//     on the layout's move strip;
//   - the attack in progress outlined for everyone (`active` attacker, `target` defender);
//   - the clicked card's stats on the layout's stat counters (cost / speed / power / health);
//   - dice through the seat's dice dock (`world.requestRoll`); a bot's dice clear after 10 s.
// Every module-level name starts with "tx" (the kernel extractor matches names).
// ============================================================================================
const TX_DECIDE = "swtcg-decide";
const TX_CARD = "swtcg-card";
/** Seconds a bot's (host-rolled) dice stay on the table. */
const TX_BOT_DICE_CLEAR = 10;
/** Searchable choice lists (`choices.search`): on once the platform ships them. */
const TX_SEARCH_LISTS = true;
/** The no-card moves on the move strip: button id -> move. */
let txHudMoves = {};
/** The open decision prompt: button / option id -> move. */
let txDecideMoves = {};
/** The open card prompt (a click on a card with several options). */
let txCardPrompt = null;
/** The roll the seat's dice dock is asked for: the move count it belongs to (one request per roll). */
let txRollReq = null;
/** Who sees a prompt for `seat`: that seat only; in practice (nobody seated) everyone. */
function txAudienceFor(seat) {
    return txPractice ? { allow: ["spectators"] } : { audience: { scope: "seats", seats: [txSeats[seat]] } };
}
function txInstOfEntity(entityId) {
    for (const key of Object.keys(txEnts)) {
        if (txEnts[Number(key)].id === entityId)
            return Number(key);
    }
    return -1;
}
function txEntityOf(inst) {
    const ent = inst >= 0 ? txEnts[inst] : undefined;
    return ent ? ent.id : null;
}
// ------------------------------------------------------------------------------ highlights --
/** Outline the attack for everyone and, for the deciding person, what they can act on. */
function txRefreshHighlights(s) {
    world.clearHighlights();
    if (s.win >= 0)
        return;
    const attacker = s.atk ? s.atk.a : s.ph === "attack-target" || s.ph === "double" ? s.sel : -1;
    const a = txEntityOf(attacker);
    if (a)
        world.setHighlight(a, "active");
    const d = s.atk ? txEntityOf(s.atk.d) : null;
    if (d)
        world.setHighlight(d, "target");
    const seat = s.who;
    if (txIsBotSeat(seat) || s.ph === "roll")
        return;
    const info = choiceInfo(s);
    const insts = info ? info.options.map((o) => (o.cardInst === undefined ? -1 : o.cardInst)) : playableNow(s, seat);
    const ids = [];
    for (const inst of insts) {
        const id = txEntityOf(inst);
        if (id && ids.indexOf(id) < 0 && id !== a)
            ids.push(id);
    }
    if (ids.length === 0)
        return;
    const style = info && info.kind === "card" && s.ph !== "choose-attacker" ? "target" : "playable";
    world.setHighlight(ids, style, txPractice ? undefined : { seats: [txSeats[seat]] });
}
// ------------------------------------------------------------------------------ menus / strip --
function txSetMovesOpen(seat, open) {
    if (txPractice) {
        txHudSet("movesOpenAll", open);
        return;
    }
    txHudSet("movesOpen", open, txSeats[seat], true);
}
/** Clear every offer: card menus, the move strip, the prompts and the card stats. */
function txClearMenus() {
    for (const id of txMenuIds)
        world.removeObjectMenuItem(id);
    txMenuIds = [];
    txMenuMoves = [];
    txHudMoves = {};
    txDecideMoves = {};
    if (txCardPrompt)
        ui.hide(TX_CARD);
    txCardPrompt = null;
    ui.hide(TX_DECIDE);
    for (let seat = 0; seat < 2; seat += 1) {
        txSetMovesOpen(seat, false);
        txHudSet("cardOpen", false, txSeats[seat], true);
    }
}
/** The seat's no-card moves on the layout's move strip (a list prompt when there are many). */
function txShowStrip(seat, buttons) {
    if (buttons.length === 0)
        return;
    if (buttons.length <= 12) {
        ui.show("swtcg-moves", { actions: buttons, title: "Your move" });
        txSetMovesOpen(seat, true);
        return;
    }
    ui.show({
        id: TX_DECIDE,
        kind: "prompt",
        placement: { region: "sheet" },
        title: "Choose",
        ...txAudienceFor(seat),
        choices: { options: buttons.slice(0, 200), ...(TX_SEARCH_LISTS ? { search: true } : {}) }
    });
}
/** What a decision is about, in one line under its title. */
function txDecisionBody(s, info) {
    const parts = [];
    const pop = popInfo(s);
    if (pop)
        parts.push(pop.charAt(0).toUpperCase() + pop.slice(1) + ".");
    if (info.max > 1)
        parts.push("Chosen " + info.picked + " of up to " + info.max + ".");
    if (info.kind === "card")
        parts.push("Pick below, or click an outlined card.");
    return parts.join(" ").slice(0, 480);
}
/** The open decision as ONE prompt to the deciding seat. */
function txShowDecision(s, info) {
    txDecideMoves = {};
    const options = info.options.map((o, i) => {
        const id = "d" + txMenuVer + "-" + i;
        txDecideMoves[id] = o.move;
        const option = { id, label: o.label.slice(0, 120) };
        const ent = o.cardInst === undefined ? null : txEntityOf(o.cardInst);
        if (ent)
            option.entityId = ent;
        return option;
    });
    const many = options.length > 12 || info.search;
    ui.show({
        id: TX_DECIDE,
        kind: "prompt",
        placement: { region: "sheet" },
        title: info.title.slice(0, 200),
        body: txDecisionBody(s, info),
        ...txAudienceFor(info.seat),
        ...(many
            ? { choices: { options: options.slice(0, 200), ...(TX_SEARCH_LISTS ? { search: true } : {}) } }
            : { actions: options.map((o) => ({ id: o.id, label: o.label })) })
    });
}
/** Offer the deciding seat its moves: a decision prompt, or cards + menus + the move strip. */
function txRebuildMenus() {
    txClearMenus();
    const s = txState;
    if (!s)
        return;
    txRefreshHighlights(s);
    if (s.win >= 0)
        return;
    const seat = s.who;
    if (txIsBotSeat(seat))
        return;
    txMenuVer += 1;
    txMenuSeat = seat;
    if (s.ph === "roll") {
        txRequestHumanRoll(s, seat);
        return;
    }
    const info = choiceInfo(s);
    if (info) {
        txShowDecision(s, info);
        return;
    }
    const map = cellMapOf(s, seat);
    const primary = txPrimaryMove(s, seat);
    const loose = [];
    const tail = [];
    legalMoves(s).forEach((m, i) => {
        const inst = m.r >= 0 ? map.instOf[m.r] : -1;
        const ent = inst >= 0 ? txEnts[inst] : undefined;
        if (!ent) {
            const hudId = "m" + txMenuVer + "-" + i;
            txHudMoves[hudId] = m;
            const label = moveLabel(s, m).slice(0, 120);
            if (primary && primary.r === m.r && primary.a === m.a)
                tail.push({ id: hudId, label, icon: "skip_next", emphasis: "strong" });
            else
                loose.push({ id: hudId, label });
            return;
        }
        // Right-click menus stay for people who prefer them; a left click opens the same options.
        const id = "swm-" + txMenuVer + "-" + i;
        const item = {
            id,
            label: moveLabel(s, m).slice(0, 80),
            match: { objectIds: [ent.id] },
            order: i
        };
        if (!txPractice)
            item.seats = [txSeats[seat]];
        world.addObjectMenuItem(item);
        txMenuIds.push(id);
        txMenuMoves[i] = m;
    });
    txShowStrip(seat, loose.concat(tail));
}
// ------------------------------------------------------------------------------ card clicks --
/** A card's stats for the HUD counters: printed cost and speed, live power and health. */
function txShowCardInfo(s, inst, seatId) {
    if (!seatId || !s.cards[inst])
        return;
    const c = card(s, inst);
    const viewer = txSeats.indexOf(seatId);
    // Never a hidden card's stats: face down, or another player's hand.
    if (c.fd || (c.z === "hand" && c.o !== viewer))
        return;
    const d = defOf(s, inst);
    const unit = isUnitDef(d);
    const live = unit ? stats(s, inst) : null;
    txHudSet("cardName", d.n, seatId, true);
    txHudSet("cardCost", d.costX ? "X" : String(d.cost), seatId, true);
    txHudSet("cardSpeed", unit ? String(d.sp) : "-", seatId, true);
    txHudSet("cardPower", live ? String(live.pw) : "-", seatId, true);
    txHudSet("cardHealth", live ? remainingHealth(s, inst) + "/" + live.hp : "-", seatId, true);
    txHudSet("cardOpen", true, seatId, true);
}
/** A click on a card: its stats, and its options if it is the clicker's move. */
async function txCardClicked(entityId, seatId) {
    const s = txState;
    if (!s)
        return;
    const inst = txInstOfEntity(entityId);
    if (inst < 0)
        return;
    txShowCardInfo(s, inst, txPractice ? txSeats[0] : seatId);
    const seat = txPractice ? 0 : seatId ? txSeats.indexOf(seatId) : -1;
    if (seat < 0 || s.win >= 0 || s.who !== seat || txIsBotSeat(seat) || s.ph === "roll")
        return;
    const options = movesFor(s, inst);
    if (options.length === 0)
        return;
    const info = choiceInfo(s);
    // Answering a "pick a card" decision, or the one thing this card can do in it: a click is enough.
    if (options.length === 1 && info) {
        await txHumanPlay(options[0].move);
        return;
    }
    const moves = {};
    const buttons = options.map((o, i) => {
        const id = "c" + txMenuVer + "-" + i;
        moves[id] = o.move;
        return { id, label: o.label.slice(0, 120) };
    });
    txCardPrompt = { seat, ver: txMenuVer, moves };
    const cancel = { id: "cancel", label: "Cancel", icon: "close", emphasis: "subtle" };
    ui.show({
        id: TX_CARD,
        kind: "prompt",
        placement: { region: "sheet" },
        title: nameOf(s, inst).slice(0, 200),
        body: "What should " + nameOf(s, inst) + " do?",
        ...txAudienceFor(seat),
        ...(buttons.length <= 11
            ? { actions: buttons.concat([cancel]) }
            : { choices: { options: buttons.slice(0, 199).concat([cancel]) } })
    });
}
globalEvents.onObjectClicked.add((object, context) => {
    const seatId = context.seat;
    void txRun(async () => {
        await txCardClicked(object.id, seatId);
    });
});
// ------------------------------------------------------------------------------ HUD presses --
ui.onAction.add((event) => {
    if (event.widgetId === "swtcg-game") {
        if (event.actionId !== "new-game")
            return;
        if (!txPractice && event.seat === null)
            return;
        const running = typeof match !== "undefined" ? match.current() : null;
        if (running && running.ranked && running.status === "live" && !txOver) {
            // Only the person who pressed hears it (the actor audience works before the first await).
            ui.toast("A ranked match is being played: finish it or resign before starting a new game.", { tone: "warning", to: { scope: "actor" } });
            return;
        }
        void txRun(async () => {
            await txNewGame();
        });
        return;
    }
    const wid = event.widgetId;
    if (wid !== "swtcg-moves" && wid !== TX_DECIDE && wid !== TX_CARD)
        return;
    if (event.dismissed || !event.actionId)
        return;
    const id = event.actionId;
    const seatId = event.seat;
    void txRun(async () => {
        const s = txState;
        if (!s || s.win >= 0 || s.who !== txMenuSeat)
            return;
        // The host checked the presser is in the widget's audience; still, only the deciding seat moves.
        if (!txPractice && seatId !== txSeats[s.who])
            return;
        let m;
        if (wid === "swtcg-moves")
            m = txHudMoves[id];
        else if (wid === TX_DECIDE)
            m = txDecideMoves[id];
        else {
            const prompt = txCardPrompt;
            txCardPrompt = null;
            ui.hide(TX_CARD);
            if (id === "cancel" || !prompt || prompt.ver !== txMenuVer)
                return;
            m = prompt.moves[id];
        }
        if (!m)
            return;
        await txHumanPlay(m);
    });
});
// ------------------------------------------------------------------------------ dice --
/** What a roll is for, on the dice dock. */
function txRollLabel(s) {
    if (s.rollWhy === "build")
        return "Build roll";
    return s.atk ? (nameOf(s, s.atk.a) + " attacks").slice(0, 60) : "Attack roll";
}
/**
 * Ask `seat` to roll `n` d6 (its own seat die) and wait for the faces. A bot's or an empty seat's
 * dice are rolled by the host at once and cleared after TX_BOT_DICE_CLEAR seconds; a person rolls
 * from the dice dock or their tray. A die that cannot be read counts as a logged random face.
 */
async function txRequestDice(s, seat, n, byBot) {
    const faces = [];
    try {
        const res = await world.requestRoll(txSeats[seat], {
            dice: { sides: 6, count: n },
            area: byBot ? "table" : "tray",
            label: txRollLabel(s),
            ...(byBot ? { clearAfterSeconds: TX_BOT_DICE_CLEAR } : { timeoutSeconds: 180, onTimeout: "roll" })
        });
        if (res.result) {
            for (const d of res.result.dice)
                if (d.sides === 6 && typeof d.value === "number" && d.value >= 1 && d.value <= 6)
                    faces.push(d.value);
        }
    }
    catch (error) {
        world.log("SWTCG: the dice could not be rolled (" + txDescribe(error) + ").");
    }
    while (faces.length < n) {
        const stand = 1 + Math.floor(Math.random() * 6);
        ui.log("A die could not be read; it counts as " + stand + ".", { tone: "warning" });
        faces.push(stand);
    }
    return faces.slice(0, n);
}
/** Roll the pending dice for `seat` now (a bot, inside its turn). */
async function txRollFor(seat) {
    const s = txState;
    if (!s || s.ph !== "roll" || s.who !== seat)
        return;
    await txFeedDice(await txRequestDice(s, seat, txDiceLeft(s), true));
}
/**
 * A person's roll: the dice dock shows the request ("Roll 3d6 · tray"); the answer arrives later,
 * outside the script's queue, so nothing else waits on a person picking up their dice.
 */
function txRequestHumanRoll(s, seat) {
    const key = txMoves.length;
    if (txRollReq && txRollReq.key === key && txRollReq.seat === seat)
        return;
    txRollReq = { key, seat };
    const n = txDiceLeft(s);
    void (async () => {
        const faces = await txRequestDice(s, seat, n, false);
        void txRun(async () => {
            const now = txState;
            if (!now || now.ph !== "roll" || now.who !== seat || txMoves.length !== key)
                return;
            txRollReq = null;
            txHumanMoved = true;
            await txFeedDice(faces.slice(0, txDiceLeft(now)));
            await txAfterMoves();
            await txDriveBots();
            await txAfterMoves();
        });
    })();
}
/** Drop any open dice request (a new game, a takeback). */
function txCancelRolls() {
    if (txRollReq)
        world.cancelRollRequest(txSeats[txRollReq.seat]);
    txRollReq = null;
}
